<?php declare(strict_types=1); use App\Admin\DTO\CompanyImportData; require __DIR__.'/admin-empresa-action-common.php'; admin_empresa_post(); [$app,$session,$user]=admin_empresa_context(); try{$app->companyAdmin()->import(CompanyImportData::fromArray($_POST),$user->id(),$app->soSupplierService());$session->flash('success','Empresa importada do SO com sucesso.');}catch(InvalidArgumentException $e){$session->flash('danger',$e->getMessage());}catch(Throwable $e){error_log('Company SO import failed: '.get_class($e));$session->flash('danger','Não foi possível importar a empresa do SO.');}admin_empresa_redirect($app,'admin-empresas.php?tab=so');
